/* Independent audition source; replace it with Living Circuits voice mix at integration. */
class Afterimage extends AudioWorkletProcessor{
 constructor(){super();this.rack=new globalThis.CobaliteFX.Rack(sampleRate);this.settings=null;this.voices=[];this.phase=0;this.tick=0;this.mod=0;this.hz=.22;this.port.onmessage=({data:d})=>{if(d.type==="settings"){this.settings=d;this.rack.setWet(d.wet);}if(d.type==="on"){for(const v of this.voices)if(v.id===d.id)v.off=true;if(this.voices.length>=16)this.voices.shift();this.voices.push({id:d.id,phase:0,inc:440*Math.pow(2,(d.n-69)/12)/sampleRate,env:0,off:false,age:0});}if(d.type==="off")for(const v of this.voices)if(v.id===d.id)v.off=true;if(d.type==="panic"){this.voices.length=0;this.rack.clear();}};}
 process(inputs,outputs){const out=outputs[0],s=this.settings;if(!s)return true;const n=out[0].length,dt=n/sampleRate,route=s.route;const sensors=this.rack.sensors;this.hz=route?Math.max(.005,Math.min(8,route.rate*Math.pow(2,route.influence*4*sensors[route.sensor]))):0;this.phase=(this.phase+dt*this.hz)%1;this.mod+=( (route?Math.sin(this.phase*2*Math.PI)*route.depth:0)-this.mod)*(1-Math.exp(-dt/.04));for(let i=0;i<3;i++){const t=s.slots[i],p=t.p;let a=p[0],b=p[1],c=p[2];if(route&&route.slot===i){if(route.param===0)a+=this.mod;else if(route.param===1)b+=this.mod;else c+=this.mod;}this.rack.configure(i,t.type,a,b,c,t.mix);}const atk=1-Math.exp(-1/(sampleRate*.008)),rel=1-Math.exp(-1/(sampleRate*.09));for(let j=0;j<n;j++){let x=0;for(const v of this.voices){v.phase=(v.phase+v.inc)%1;v.age+=1/sampleRate;v.env+=((v.off?0:1)-v.env)*(v.off?rel:atk);const p=v.phase*2*Math.PI;const signal=s.source==="sharp"?.64*Math.sin(p)+.25*Math.sin(2*p)+.11*Math.sin(3*p):s.source==="pluck"?(.7*Math.sin(p)+.3*Math.sin(3*p))*Math.exp(-v.age*3):.85*Math.sin(p)+.15*Math.sin(2*p);x+=signal*v.env*.085;}this.rack.process(x,x);out[0][j]=Math.tanh(this.rack.outL);out[1][j]=Math.tanh(this.rack.outR);}for(let i=this.voices.length-1;i>=0;i--)if(this.voices[i].off&&this.voices[i].env<.0001)this.voices.splice(i,1);this.rack.endBlock();if(++this.tick>=16){this.tick=0;this.port.postMessage({type:"telemetry",sensors:this.rack.sensors,hz:this.hz,mod:this.mod});}return true;}
}
registerProcessor("afterimage",Afterimage);
